from contextlib import closing
import sqlite3


class Service:
    def __init__(self, path):
        self.path = path
        with closing(sqlite3.connect(path, timeout=2)) as db:
            db.executescript('''
                CREATE TABLE IF NOT EXISTS accounts(account TEXT PRIMARY KEY,remaining INTEGER NOT NULL);
                CREATE TABLE IF NOT EXISTS decisions(key TEXT PRIMARY KEY,account TEXT,amount INTEGER,status TEXT,remaining INTEGER);
                CREATE TABLE IF NOT EXISTS ledger(key TEXT PRIMARY KEY,account TEXT,amount INTEGER);
                INSERT OR IGNORE INTO accounts VALUES('A',100);
                INSERT OR IGNORE INTO accounts VALUES('B',100);
            ''')

    def apply(self, request):
        key, account, amount = request['key'], request['account'], request['amount']
        with closing(sqlite3.connect(self.path, timeout=2, isolation_level=None)) as db:
            db.execute('BEGIN IMMEDIATE')
            try:
                prior = db.execute('SELECT account,amount,status,remaining FROM decisions WHERE key=?', (key,)).fetchone()
                if prior:
                    if (account, amount) != prior[:2]:
                        result = dict(status='payload_mismatch', remaining=None)
                    else:
                        result = dict(status=prior[2], remaining=prior[3])
                else:
                    changed = db.execute('UPDATE accounts SET remaining=remaining-? WHERE account=? AND remaining>=?',
                                         (amount, account, amount)).rowcount
                    remaining = db.execute('SELECT remaining FROM accounts WHERE account=?', (account,)).fetchone()[0]
                    status = 'applied' if changed else 'rejected'
                    if changed:
                        pass
                    db.execute('INSERT INTO decisions VALUES(?,?,?,?,?)', (key, account, amount, status, remaining))
                    result = dict(status=status, remaining=remaining)
                db.execute('COMMIT')
                return result
            except BaseException:
                db.execute('ROLLBACK')
                raise
